library(knowYourCG)

# Create a synthetic BED file of CpG coordinates
bed_data <- data.frame(
  chrom = c("chr1", "chr1", "chr2"),
  start = c(10000, 20000, 30000),
  end = c(10002, 20002, 30002),
  name = c("cg00000001", "cg00000002", "cg00000003")
)
write.table(bed_data, file = "input_cpgs.bed", sep = "\t", quote = FALSE, row.names = FALSE, col.names = FALSE)

# Create a synthetic YAME reference coordinate file (.cr)
# Since the actual .cr format is a specific binary/compressed format generated by YAME 
# and is not shipped with the package, we provide a dummy file to satisfy the file existence requirement.
writeLines("YAME_CR_DUMMY_CONTENT", "cpg_nocontig.cr")